static int hdr_reference_pixel(unsigned depth, unsigned full, unsigned transfer,
      unsigned y, unsigned u, unsigned v, float out[3])
{
   unsigned i, j;
   for (i = 0; i < sizeof(hdr_reference) / sizeof(hdr_reference[0]); i++)
   {
      const unsigned *r = hdr_reference[i];
      if (r[0] == depth && r[1] == full && r[2] == transfer
            && r[3] == y && r[4] == u && r[5] == v)
      {
         for (j = 0; j < 3; j++)
            out[j] = (float)r[6 + j] / 255.0f;
         return 1;
      }
   }
   return 0;
}
